const {useState, useEffect, useRef, useCallback, useMemo} = React;
// Cache-bust marker — bump this string when forcing browsers to refetch app.js
const __APP_VERSION__="media-filter-stations-2026-05-27";
// Startup banner so it's possible to confirm, from the browser console, EXACTLY
// which app.js the live site is serving. If this tag isn't in the console after a
// hard-reload, the deploy is stale and you're running old code.
try{console.log("%c⚡ DOOM build: "+__APP_VERSION__,"background:#1e1233;color:#D4A040;font-weight:700;padding:3px 8px;border-radius:4px")}catch(e){}

// HTML-escape any free-text/user-controlled value before it is concatenated
// into a string that gets written to a same-origin window via document.write
// or assigned as innerHTML. Stops stored XSS where a station/ISCI/vendor field
// (title, comments, notes, loc, contact email, file URL) carries markup like
// <img src=x onerror=...>. Use everywhere data flows into raw HTML strings.
const escHtml=(v)=>String(v==null?"":v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
// Supabase public URLs open inline; ?download forces a file download (the
// <a download> attr is ignored cross-origin). Firebase URLs already download.
const dlUrl=(u)=>!u?u:(/supabase\.co/.test(u)?u+(u.includes("?")?"&":"?")+"download":u);

// Server-side auth verification. On successful login, /api/auth may return a
// Firebase Auth custom token (when FIREBASE_ADMIN_KEY is set on the server) —
// we sign the client into Firebase Auth so writes survive locked-down Firestore
// rules. If no customToken is returned, this is a no-op and the app works as
// before.
const signInWithFbToken=async(customToken)=>{
  if(!customToken)return;
  try{
    // Firebase init runs concurrently with app.js load — wait for it to land.
    if(window._firebaseReady)await window._firebaseReady;
    if(window.fbAuth&&window.fbAuth.signInWithCustomToken){
      await window.fbAuth.signInWithCustomToken(customToken);
      console.log("Firebase Auth signed in:",window.fbAuth.currentUser&&window.fbAuth.currentUser.uid);
    }
  }catch(e){console.warn("Firebase Auth signin failed:",e&&e.message)}
};
// Pick up a custom token stashed by the index.html loader (the initial password
// prompt) so first-page-loads also sign into Firebase Auth.
if(typeof window!=="undefined"&&window.__pendingCustomToken){
  signInWithFbToken(window.__pendingCustomToken);
  window.__pendingCustomToken=null;
}
const verifyAuth=async(password,type,pin)=>{
  try{
    const r=await fetch("/api/auth",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({password,pin,type})});
    const d=await r.json();
    if(d.success===true&&type==="login"){
      try{
        if(d.user)sessionStorage.setItem("dd_user",d.user);
        sessionStorage.setItem("dd_role",d.role||"member");
      }catch(e){}
      if(d.customToken){await signInWithFbToken(d.customToken)}
    }
    return d.success===true;
  }catch(e){console.error("Auth check failed:",e);return false}
};
// Who is signed in (set by the login flow / session check). Used to stamp the
// activity log so edits are attributable per person, not a generic label.
const currentUser=()=>{try{return sessionStorage.getItem("dd_user")||"Staff"}catch(e){return "Staff"}};
const currentRole=()=>{try{return sessionStorage.getItem("dd_role")||"member"}catch(e){return "member"}};
const isManagerRole=()=>{const r=currentRole();return r==="owner"||r==="admin"};
const signOut=async()=>{
  try{await fetch("/api/auth",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:"logout"})})}catch(e){}
  try{["dd_auth","dd_user","dd_role","dd_mustchange"].forEach(k=>sessionStorage.removeItem(k))}catch(e){}
  try{if(window.fbAuth&&window.fbAuth.signOut)window.fbAuth.signOut()}catch(e){}
  window.location.reload();
};
// Friendly names for the stored collections — used in the save-failed and
