                const shouldLink=ESTIMATES.filter(e=>e.brand==="Wettermark Keith"&&e.market===sMarket&&mediaCompat(sta.media,e.media)).map(e=>e.num);
                const merged=[...new Set([...cleaned,...shouldLink])];
