  // ── CONFIRMATION REMINDERS (manual trigger) ──────────────────
  const sendConfirmReminders=async()=>{
    const now=Date.now();const HOURS_24=24*60*60*1000;
    const toRemind=[];
    trafficHistory.forEach(h=>{
      if(!h.est||!h.stations||!h.stations.length||!h.ts)return;
      if(h.status!=="sent"&&h.status!=="partial")return;
      const sentAt=new Date(h.ts).getTime();
      if(now-sentAt<HOURS_24)return;
      const conf=confirmations[akFromHistory(h)]||{};
      h.stations.forEach(call=>{
        if(conf[call]?.confirmed)return;
        const rKey=akFromHistory(h)+"_"+call+"_v"+(h.version||"1");
        if(confirmRemindersSent[rKey])return;
        const sta=stations.find(s=>s.call===call);
        if(!sta)return;
        const emails=(sta.contact||"").split(";").map(e=>e.trim()).filter(e=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e));
        if(!emails.length)return;
        toRemind.push({h,call,sta,emails,rKey});
      });
    });
    if(!toRemind.length){notify("No pending reminders — all stations confirmed or already reminded");return}
    if(!confirm("Send confirmation reminders to "+toRemind.length+" unconfirmed station(s)?"))return;
    notify("Sending "+toRemind.length+" reminder(s)...");
    // Ensure every reminded station has a real token stored before any URL is built.
    // We mutate confirmations once with all the needed tokens so vendors who click later
    // can be validated against the persisted value.
    const tokensByKey={};toRemind.forEach(r=>{const k=akFromHistory(r.h);const existing=confirmations[k]?.[r.call]?.token;tokensByKey[k]=tokensByKey[k]||{};tokensByKey[k][r.call]=existing||genToken()});
    setConfirmations(p=>{const next={...p};Object.entries(tokensByKey).forEach(([k,calls])=>{next[k]={...(next[k]||{})};Object.entries(calls).forEach(([call,token])=>{if(!next[k][call])next[k][call]={confirmed:false,token};else if(!next[k][call].token)next[k][call]={...next[k][call],token}})});try{db.collection("appData").doc("confirmations").set({data:JSON.stringify(next),ts:Date.now()})}catch(e){console.warn("Failed to save confirmations:",e)}return next});
    const newReminders={};let sent=0;let failed=0;
    for(const r of toRemind){
      const mktName=DM[r.h.market]||r.h.market||"";
      const subj="Reminder: Please Confirm Traffic Receipt — "+r.h.brand+" "+mktName+" "+r.h.media+" | Est "+(r.h.est||"");
      const baseUrl=window.location.href.split("?")[0].split("#")[0];
      const remTok=tokensByKey[akFromHistory(r.h)]?.[r.call]||"";
      const confirmUrl=baseUrl+"?confirm="+encodeURIComponent(r.h.est||"")+"&sta="+encodeURIComponent(r.call)+"&tok="+encodeURIComponent(remTok);
      const isciObjs=(r.h.iscis||[]).map(ic=>{const full=iscis.find(i=>i.code===ic.code);return full?{code:ic.code,title:ic.title,fileUrl:full.fileUrl}:null}).filter(Boolean);
      const creativeLinks=isciObjs.filter(i=>i.fileUrl).length>0?"<br><br><b>Creative Files:</b><br>"+isciObjs.filter(i=>i.fileUrl).map(i=>'<a href="'+dlUrl(i.fileUrl)+'">'+i.code+" — "+i.title+'</a>').join("<br>"):"";
      const body="Hello,<br><br>This is a reminder that you have not yet confirmed receipt of traffic instructions for <b>"+(r.h.est||"")+" — "+r.h.brand+", "+mktName+", "+r.h.media+"</b>.<br><br><b>Broadcast Month:</b> "+(r.h.month||"")+"<br><b>Flight Dates:</b> "+(r.h.flight||"")+"<br><b>Version:</b> "+r.h.version+"<br><b>Station:</b> "+r.call+creativeLinks+"<br><br>The traffic sheet is attached for your reference.<br><br>Please confirm receipt by clicking the link below:<br><a href=\""+confirmUrl+"\">Confirm Receipt</a><br><br>Thank you,<br><br>Emm Caban<br>Atticor";
      let pdfB64="";try{const sheetHtml=bldHtml(r.h);const pdfUri=await generatePdfBase64(sheetHtml,r.h);pdfB64=pdfUri.split(",")[1]||""}catch(pe){console.warn("PDF gen failed:",pe)}
      const pdfName="Traffic_"+r.h.brand.replace(/\s/g,"")+"_"+mktName.replace(/\s/g,"")+"_"+r.h.media+"_"+(r.h.month||"").replace(/\s/g,"")+"_v"+r.h.version+".pdf";
      try{
        const resp=await fetch("/api/send-traffic",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({to:r.emails.join(","),cc:[BUYER_EMAILS[r.h.buyer]||"","emm.caban@atticor.ai"].filter(Boolean).join(","),subject:subj,message:body,pdfBase64:pdfB64,pdfName:pdfName})});
        if(resp.ok){newReminders[r.rKey]={ts:now,to:r.emails.join(",")};sent++;log("Confirm Reminder",r.call+" — Est "+r.h.est+" "+r.h.market+" "+r.h.media)}
      }catch(e){
        failed++;log("Reminder Failed",r.call+" — Est "+r.h.est+" "+r.h.market);
      }
    }
    if(Object.keys(newReminders).length>0)setConfirmRemindersSent(p=>({...p,...newReminders}));
    notify(sent+" reminder(s) sent"+(failed?" · "+failed+" failed":""));
  };

  // ── STATION ↔ ESTIMATE AUTO-LINKING ────────────────────
  // Key: "call|market|brand" → [estNums]
  // Auto-initialize: link stations to estimates in same market + brand + compatible media
  const buildDefaultLinks=(stationsList,estimatesList)=>{
    const links={};
    const mediaCompat=(sMed,eMed)=>{
      if(sMed===eMed)return true;
      return false;
    };
    stationsList.forEach(s=>{
      const key=`${s.call}|${s.market}|${s.brand}`;
      const matched=estimatesList.filter(e=>e.market===s.market&&e.brand===s.brand&&mediaCompat(s.media,e.media)).map(e=>e.num);
      if(matched.length)links[key]=matched;
    });
    return links;
  };
  const[staEstLinks,setStaEstLinks]=useState({});
  const staKey=(s)=>`${s.call}|${s.market}|${s.brand}`;
  const getStaEsts=(s)=>staEstLinks[staKey(s)]||[];
  const toggleStaEst=(s,estNum)=>{
    const k=staKey(s);
    setStaEstLinks(p=>{const cur=p[k]||[];return{...p,[k]:cur.includes(estNum)?cur.filter(n=>n!==estNum):[...cur,estNum]}});
  };
  const getEstStations=(est)=>{
    const em=est.market?normMkt(est.market)||est.market:"";
    const eMedia=String(est.media||"").toLowerCase();
    return stations.filter(s=>{
      if(em){const sm=normMkt(s.market)||s.market;if(sm!==em&&s.market!==est.market)return false}
      // Media must match — WK monthly estimates (e.g. 215) are shared across ALL
      // media, so without this filter a Radio estimate would also match TV stations
      // linked to the same estimate number.
      if(eMedia&&String(s.media||"").toLowerCase()!==eMedia)return false;
      const linked=staEstLinks[staKey(s)]||[];return linked.includes(est.num);
    });
  };

  // ── NOW AIRING / CONFIRMATIONS ──────────────────────────
  // Key helper: WK 3-digit estimates shared across markets need market in key
  const[nowAiring,setNowAiring]=useState({});
